function p3_check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks++;echo 'PASS: '.$label.PHP_EOL;}
function p3_client():CurlHandle{$c=curl_init();curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_COOKIEFILE=>'',CURLOPT_TIMEOUT=>15]);return$c;}
function p3_request(CurlHandle $c,string $path,string $method='GET',?string $body=null,array $headers=[]):array{global$base;curl_setopt_array($c,[CURLOPT_URL=>$base.$path,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_POSTFIELDS=>$body,CURLOPT_HTTPHEADER=>$headers]);$raw=curl_exec($c);if($raw===false)throw new RuntimeException(curl_error($c));$size=curl_getinfo($c,CURLINFO_HEADER_SIZE);$content=substr($raw,$size);return['status'=>curl_getinfo($c,CURLINFO_RESPONSE_CODE),'headers'=>substr($raw,0,$size),'body'=>$content,'json'=>json_decode($content,true)];}
function p3_api(array|string $body,?string $key=null):array{$headers=['Content-Type: application/json','Accept: application/json'];if($key!==null)$headers[]='X-Device-Key: '.$key;return p3_request(p3_client(),'/api/device/telemetry.php','POST',is_string($body)?$body:json_encode($body),$headers);}
function p3_token(array $response):string{preg_match('/name="csrf_token" value="([a-f0-9]{64})"/',$response['body'],$m);if(!isset($m[1]))throw new RuntimeException('Missing CSRF token.');return$m[1];}
function p3_login(CurlHandle $c,string $email,string $password):void{$form=p3_request($c,'/public/login.php');$reply=p3_request($c,'/public/login.php','POST',http_build_query(['csrf_token'=>p3_token($form),'email'=>$email,'password'=>$password]),['Content-Type: application/x-www-form-urlencoded']);p3_check($reply['status']===303,'Phase 3 test user authenticated');}
