 $uuid='123e4567-e89b-42d3-a456-426614174000';$body=['device_id'=>$prefix.'D','grease_trap_id'=>$ids['traps'][0],'ultrasonic_distance'=>12.4,'waste_level_percent'=>58,'reading_uuid'=>$uuid,'temperature'=>31.5,'turbidity'=>250,'flow_rate'=>1.8,'gas_value'=>120];
