 p3_check(!phase3_simulator_available('production'),'Simulator is unavailable in production mode');$pdo->prepare('UPDATE devices SET last_seen_at=NULL WHERE id=?')->execute([$device]);$simForm=p3_request($admin,'/admin/telemetry-simulator.php');$simReply=p3_request($admin,'/admin/telemetry-simulator.php','POST',http_build_query(['csrf_token'=>p3_token($simForm),'device_id'=>$device,'grease_trap_id'=>$ids['traps'][0],'device_key'=>$key,'ultrasonic_distance'=>'11.25']),['Content-Type: application/x-www-form-urlencoded']);p3_check($simReply['status']===200&&(int)$pdo->query('SELECT COUNT(*) FROM sensor_readings WHERE device_assignment_id='.$assignment.' AND is_simulated=1')->fetchColumn()===1,'Development simulator uses the real telemetry API');
 $devicePage=p3_request($admin,'/admin/device-view.php?id='.$device);$rotate=p3_request($admin,'/admin/devices.php','POST',http_build_query(['csrf_token'=>p3_token($devicePage),'action'=>'credential','id'=>$device]),['Content-Type: application/x-www-form-urlencoded']);$credentialPage=p3_request($admin,'/admin/device-view.php?id='.$device);preg_match('/<code>([a-f0-9]{64})<\/code>/',$credentialPage['body'],$credentialMatch);$newKey=$credentialMatch[1]??'';p3_check($rotate['status']===303&&strlen($newKey)===64&&hash_equals((string)$pdo->query('SELECT api_key_hash FROM devices WHERE id='.$device)->fetchColumn(),hash('sha256',$newKey)),'Administrator can generate and rotate a hashed device credential');$hiddenAgain=p3_request($admin,'/admin/device-view.php?id='.$device);p3_check(!str_contains($hiddenAgain['body'],$newKey)&&p3_api($body,$key)['status']===401,'Plaintext credential is shown once and the previous key is revoked');
